TFL={'id':lambda g:g,'fH':lambda g:g[:,::-1],'fV':lambda g:g[::-1,:],'r180':lambda g:g[::-1,::-1]}
# Clean solver: propagate direct transpose partners repeatedly (phase A), then fill remaining comps
# by best (source, transform) with EXACT match requirement relaxed to MAXIMUM overlap; if none exists, skip.
def solve(I, max_epochs=50, allow_partial=False):
    I=np.array(I); H,W=I.shape
    lab,n=ndimage.label(I==6)
    res=I.copy()
    # phase A: flood propagate over transpose graph: 6-cell takes value of any known diag partner
    changed=True
    for _ in range(max_epochs):
        if not changed: break
        changed=False
        for r in range(H):
            for c in range(W):
                if res[r,c]!=6: continue
                pr,pc=c,r
                if 0<=pr<H and 0<=pc<W and res[pr,pc]!=6:
                    res[r,c]=res[pr,pc]; changed=True
    # phase B: each remaining comp -> best exact or partial same-shape source transform, prefer more agreements
    for k in range(1,n+1):
        ys,xs=np.where(lab==k)
        r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
        fh,fw=r1-r0+1,c1-c0+1
        tb=None; best=None
        for tn,Tf in TFL.items():
            tgt=res[r0:r1+1,c0:c1+1]
            tb=Tf(tgt)
            if (tb==6).any(): continue
            found=False
            for R in range(H-tb.shape[0]+1):
                for C in range(W-tb.shape[1]+1):
                    blk=I[R:R+fh,C:C+fw]
                    if (blk==6).any(): continue
                    agree=int(((tb!=6)&(blk!=6)&(tb==blk)).sum())
                    key=(-agree,-R,-C)
                    if best is None or key>best[0]: best=(key,tn,R,C)
        if best is None:
            # skip or try identity without flip
            continue
        _,tn,R,C=best
        res[r0:r1+1,c0:c1+1]=TFL[tn](I[R:R+fh,C:C+fw])
    return res.tolist()
for dk in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    pred=solve(G[dk+' input']); exp=G[dk+' output']
    bad=[(r,c,pred[r][c],exp[r][c]) for r in range(30) for c in range(30) if pred[r][c]!=exp[r][c]]
    print(dk,'mismatch:',len(bad),bad[:3])

