G=load()
from collections import deque
def solve(I):
    I=np.array(I); H,W=I.shape
    res=I.copy()
    # phase A: propagate known transpose partners
    changed=True
    while changed:
        changed=False
        for r in range(H):
            for c in range(W):
                if res[r,c]!=6: continue
                pr,pc=c,r
                if 0<=pr<H and 0<=pc<W and res[pr,pc]!=6:
                    res[r,c]=res[pr,pc]; changed=True
    # phase B: BFS over non-6 (non-wall) cells; each unresolved 6-cell gets nearest non-6 value
    # via multi-source BFS where 6-cells are sources; dist propagated over cells !=6; record value of reaching cell
    dist={}; valof={}
    dq=deque()
    for r in range(H):
        for c in range(W):
            if res[r,c]!=6:
                dist[(r,c)]=0; valof[(r,c)]=int(res[r,c]); dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        cur=int(dist[(r,c)])
        for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
            if 0<=rr<H and 0<=cc<W and (rr,cc) not in dist:
                dist[(rr,cc)]=cur+1; valof[(rr,cc)]=int(res[r,c])
                dq.append((rr,cc))
    # unresolved cells (still 6 after A) get nearest value
    unresolved={(r,c) for r in range(H) for c in range(W) if res[r,c]==6}
    rem=list(unresolved-set(np.argwhere([dist.get((r,c) is not None for _ in [])])) ) if False else sorted(unresolved)
    for r,c in rem:
        cand=[]
        for (rr,cc),dv in dist.items():
            # valid if path didn't pass through another unresolved cell? ignore; accept nearest overall
            if res[rr,cc]!=6:
                cand.append((dv,int(valof[(rr,cc)])))
        if cand:
            dv,v=min(cand)
            res[r,c]=v
    return res.tolist()
for dk in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    pred=solve(G[dk+' input']); exp=G[dk+' output']
    bad=[(r,c,pred[r][c],exp[r][c]) for r in range(30) for c in range(30) if pred[r][c]!=exp[r][c]]
