import numpy as np, os, re, json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from scipy import ndimage
def dihs(a):
    seen=set(); outs=[]
    for fl in range(2):
        b=np.fliplr(a) if fl else a
        for k_ in range(4):
            o=np.rot90(b,k_)
            key=o.tobytes()
            if key not in seen: seen.add(key); outs.append(o)
    return outs
# Band rule: for each comp, search SAME ROW BAND clean windows of same shape, choose nearest; verify on demos.
def solve_band(Iin, O=None, verbose=False):
    I=np.array(Iin); H,W=I.shape
    lab,n=ndimage.label(I==6)
    res=I.copy()
    ok_all=True
    for ka in range(1,n+1):
        y,x=np.where(lab==ka)
        r0,r1=int(y.min()),int(y.max()); c0,c1=int(x.min()),int(x.max())
        th,tw=r1-r0+1,c1-c0+1
        # band: rows r0..r1 extended by half height? try same rows only first
        band_rows=[rr0 for rr0 in range(H-th+1)]
        hits=[]
        for rr in range(max(0,r0-th//2), min(H-th+1,r1+th//2+1)):
            for cc in range(W-tw+1):
                blk=I[rr:rr+th,cc:cc+tw]
                if (blk==6).any(): continue
                md=abs(rr-(r0+r1)/2)+abs(cc-(c0+c1)/2)
                hits.append((md,(rr,cc)))
        if len(hits)==1:
            md,(sr,sc)=hits[0]
            res[r0:r1+1,c0:c1+1]=dihs(I[sr:sr+th,sc:sc+tw])[0]  # placeholder
        ok_all &= bool(hits)
    return res,ok_all
